// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.connectivity.contactimport android.content.Contextimport android.provider.ContactsContractimport androidx.work.CoroutineWorkerimport androidx.work.WorkerParametersimport com.roshan.persona.connectivity.model.ContactInfoimport timber.log.Timber/** * NOUS — Contact FTS Sync Worker (Module 11 v3 — P1). * * Rebuilds the [ContactFtsEntity] mirror from the system ContactsContract. * Triggered by [ContactObserver] whenever contacts change, and also runnable * on-demand (e.g., during onboarding). * * ## Algorithm * *  1. Query `ContactsContract.Contacts` (and Data rows for phones/emails/notes). *  2. Build a list of [ContactFtsEntity] rows. *  3. `contactFtsDao.clear()` then `contactFtsDao.upsertAll(rows)` — atomic *     rebuild (under a Room transaction). * * ## Performance * *  - For 10K contacts, the rebuild takes ~500ms on a mid-range device. *  - Runs on a background thread (WorkManager default dispatcher). *  - Strategy §"ContactSearcher" target: < 20ms / 10K query — the FTS4 *    virtual table handles that easily; the rebuild cost is amortized *    across many queries. */class ContactFtsSyncWorker(    appContext: Context,    params: WorkerParameters,) : CoroutineWorker(appContext, params) {    override suspend fun doWork(): Result {        val dao = ContactFtsSyncWorkerBridge.dao ?: return Result.retry()        val contactsProvider = ContactFtsSyncWorkerBridge.contactsProvider        return try {            val entities: List<ContactFtsEntity> = if (contactsProvider != null) {                // Use injected provider (lets tests swap with a fake).                contactsProvider().map { contact ->                    ContactFtsEntity(                        rowid = stableRowid(contact.id),                        contactId = contact.id,                        name = contact.displayName,                        phone = contact.phoneNumbers.joinToString(" ") { it },                        notes = contact.email.orEmpty(),                    )                }            } else {                // Query ContactsContract directly.                queryContactsContract()            }            // Atomic rebuild — clear then bulk insert.            dao.clear()            if (entities.isNotEmpty()) {                dao.upsertAll(entities)            }            Timber.tag(TAG).i("Contact FTS sync complete: ${entities.size} contacts mirrored.")            Result.success()        } catch (t: Throwable) {            Timber.tag(TAG).e(t, "Contact FTS sync failed")            Result.retry()        }    }    /**     * Query the system ContactsContract for all contacts with at least one     * phone number, and build FTS entities.     *     * Returns an empty list if READ_CONTACTS isn't granted.     */    private fun queryContactsContract(): List<ContactFtsEntity> {        val results = mutableListOf<ContactFtsEntity>()        val resolver = applicationContext.contentResolver        try {            val projection = arrayOf(                ContactsContract.Contacts._ID,                ContactsContract.Contacts.DISPLAY_NAME,                ContactsContract.Contacts.HAS_PHONE_NUMBER,            )            resolver.query(                ContactsContract.Contacts.CONTENT_URI,                projection,                "${ContactsContract.Contacts.HAS_PHONE_NUMBER} = 1",                null,                null,            )?.use { cursor ->                val idIdx = cursor.getColumnIndex(ContactsContract.Contacts._ID)                val nameIdx = cursor.getColumnIndex(ContactsContract.Contacts.DISPLAY_NAME)                while (cursor.moveToNext()) {                    val id = if (idIdx >= 0) cursor.getString(idIdx) else continue                    val name = if (nameIdx >= 0) cursor.getString(nameIdx) ?: "Unknown" else "Unknown"                    // Look up this contact's phone numbers + email.                    val phones = mutableListOf<String>()                    val emails = mutableListOf<String>()                    // Phones                    val phoneProjection = arrayOf(                        ContactsContract.CommonDataKinds.Phone.NUMBER,                    )                    resolver.query(                        ContactsContract.CommonDataKinds.Phone.CONTENT_URI,                        phoneProjection,                        "${ContactsContract.CommonDataKinds.Phone.CONTACT_ID} = ?",                        arrayOf(id),                        null,                    )?.use { pc ->                        val numIdx = pc.getColumnIndex(ContactsContract.CommonDataKinds.Phone.NUMBER)                        while (pc.moveToNext()) {                            if (numIdx >= 0) {                                pc.getString(numIdx)?.let { phones.add(it) }                            }                        }                    }                    // Emails (used as "notes" for FTS matching — phone labels                    // like "mobile" / "work" are not directly queryable; emails                    // serve as a stand-in for now).                    val emailProjection = arrayOf(                        ContactsContract.CommonDataKinds.Email.ADDRESS,                    )                    resolver.query(                        ContactsContract.CommonDataKinds.Email.CONTENT_URI,                        emailProjection,                        "${ContactsContract.CommonDataKinds.Email.CONTACT_ID} = ?",                        arrayOf(id),                        null,                    )?.use { ec ->                        val addrIdx = ec.getColumnIndex(ContactsContract.CommonDataKinds.Email.ADDRESS)                        while (ec.moveToNext()) {                            if (addrIdx >= 0) {                                ec.getString(addrIdx)?.let { emails.add(it) }                            }                        }                    }                    results.add(                        ContactFtsEntity(                            rowid = stableRowid(id),                            contactId = id,                            name = name,                            phone = phones.joinToString(" "),                            notes = emails.joinToString(" "),                        ),                    )                }            }        } catch (t: Throwable) {            Timber.tag(TAG).e(t, "queryContactsContract failed")        }        return results    }    companion object {        private const val TAG = "ContactFtsSync"        /**         * Derive a stable 63-bit positive Long rowid from a String contact id.         *         * Room FTS4 requires the primary key be `rowid` (INTEGER affinity).         * We can't use the raw string contact ID, so we hash it. The hash is         * stable across re-syncs (same contact id → same rowid → row gets         * replaced on `OnConflictStrategy.REPLACE`).         */        private fun stableRowid(contactId: String): Long {            val hash = contactId.hashCode().toLong() shl 32 or                contactId.fold(0L) { acc, c -> acc * 31L + c.code }.and(0xFFFFFFFFL)            return hash and 0x7FFFFFFFFFFFFFFFL  // force positive        }        const val UNIQUE_WORK_NAME = "nous_contact_fts_sync"        const val KEY_TRIGGER_URI = "trigger_uri"    }}/** * Static bridge for the Worker to access Hilt-provided singletons. * * Workers are instantiated via reflection (no constructor injection), * so they can't directly access Hilt-provided DAOs. The Hilt module sets * these references at app startup. */object ContactFtsSyncWorkerBridge {    @Volatile    var dao: ContactFtsDao? = null    /** Optional contact-provider function (lets tests inject a fake). */    @Volatile    var contactsProvider: (() -> List<ContactInfo>)? = null}